package ama.storage.s3;
import ama.contract.StorageContracts.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import org.junit.jupiter.api.Test;import software.amazon.awssdk.services.s3.S3Client;import software.amazon.awssdk.services.s3.model.*;import software.amazon.awssdk.core.sync.RequestBody;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Actual retirement protocol with an explicit in-memory S3 transport substitute. */
class Task11RetiredUploadsTest {
 static final StorageKey KEY=new StorageKey("s3","files","orphan");
 static final SessionJournal.Session SESSION=new SessionJournal.Session("12345678-1234-4234-8234-123456789abc","a".repeat(64),new UploadSpec("s3","files","orphan",0));
 static class Case {
  final S3Client client=mock(S3Client.class);final S3Objects io=spy(new S3Objects(client,new S3Config("s3",java.net.URI.create("http://127.0.0.1:1"),"us-east-1","data-test","control-test",software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("unused","unused")),true,1024,8388608,5242880L,5368709120L,10000,53687091200L,8,java.time.Duration.ofSeconds(10))));final S3Layout layout=new S3Layout(io.config);final Map<String,byte[]> controls=new HashMap<>();final List<String> order=new ArrayList<>();final AtomicBoolean fail=new AtomicBoolean();byte[] data;Map<String,String> metadata=Map.of();
  Case(){doNothing().when(io).binding(any(),any(),anyBoolean());doAnswer(x->controls.get(x.getArgument(0))).when(io).optional(anyString());doAnswer(x->{String key=x.getArgument(0);byte[] value=x.getArgument(1);var previous=controls.putIfAbsent(key,value);if(previous!=null&&!Arrays.equals(previous,value))throw new StorageException(ErrorCode.CONFLICT);order.add("marker");return null;}).when(io).exact(anyString(),any());
   when(client.putObject(any(PutObjectRequest.class),any(RequestBody.class))).thenAnswer(x->{assertTrue(controls.containsKey(RetiredUploads.markerKey(layout,KEY)));order.add("sentinel");if(fail.get())throw new StorageException(ErrorCode.STORAGE_UNAVAILABLE);PutObjectRequest req=x.getArgument(0);assertEquals(io.config.dataBucket(),req.bucket());assertEquals(layout.data(KEY),req.key());try(var in=((RequestBody)x.getArgument(1)).contentStreamProvider().newStream()){data=in.readAllBytes();}metadata=req.metadata();return PutObjectResponse.builder().eTag("sentinel-etag").build();});
   when(client.headObject(any(HeadObjectRequest.class))).thenAnswer(x->HeadObjectResponse.builder().contentLength((long)data.length).metadata(metadata).build());
  }
  void discard(){RetiredUploads.discard(io,layout,SESSION,KEY);}
 }
 @Test void permanentEntityFollowsMarkerAndCannotMasqueradeAsEmptyContent(){var c=new Case();c.discard();assertEquals(List.of("marker","sentinel"),c.order);assertTrue(c.data.length>0);assertEquals(ControlCodec.hash(c.controls.get(RetiredUploads.markerKey(c.layout,KEY))),c.metadata.get("ama-retired-v1"));assertTrue(RetiredUploads.retired(c.io,c.layout,KEY));assertThrows(StorageException.class,()->new NativePublisher(c.io,c.layout).existing(KEY,0,ControlCodec.hash(new byte[0])));verify(c.io,never()).stat(anyString());}
 @Test void existingMarkerDoesNotAcknowledgeFailedSentinelAndRetryCompletes(){var c=new Case();c.fail.set(true);assertThrows(StorageException.class,c::discard);assertTrue(RetiredUploads.retired(c.io,c.layout,KEY));assertNull(c.data);c.fail.set(false);assertDoesNotThrow(c::discard);var before=c.data.clone();assertDoesNotThrow(c::discard);assertArrayEquals(before,c.data);verify(c.client,never()).deleteObject(any(DeleteObjectRequest.class));}
 @Test void wrongKeyCannotWriteMarkerOrTouchData(){var c=new Case();assertThrows(StorageException.class,()->RetiredUploads.discard(c.io,c.layout,SESSION,new StorageKey("s3","files","foreign")));assertTrue(c.controls.isEmpty());verifyNoInteractions(c.client);}
 @Test void markerIsBoundToExactStoreSessionAndKey(){var c=new Case();c.discard();c.controls.put(RetiredUploads.markerKey(c.layout,KEY),ControlCodec.pack("discard-upload-v1","wrong-store",KEY.backendId(),SESSION.id(),SESSION.specHash(),KEY.namespace(),KEY.objectKey()));assertThrows(StorageException.class,()->RetiredUploads.retired(c.io,c.layout,KEY));}
 @Test void changedSessionCannotReuseTheSameRetiredKey(){var c=new Case();c.discard();int writes=c.order.size();var other=new SessionJournal.Session("12345678-1234-4234-8234-123456789abd",SESSION.specHash(),SESSION.spec());assertThrows(StorageException.class,()->RetiredUploads.discard(c.io,c.layout,other,KEY));assertEquals(writes,c.order.size());}
}
